CREATE TABLE tax_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), code text NOT NULL, name_ar text NOT NULL, rate numeric(7,4) NOT NULL CHECK(rate>=0), effective_from date NOT NULL, effective_to date, input_tax_account_id uuid REFERENCES accounts(id), output_tax_account_id uuid REFERENCES accounts(id), is_active boolean NOT NULL DEFAULT true, UNIQUE(company_id,code,effective_from));
CREATE TABLE tax_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), tax_code_id uuid NOT NULL REFERENCES tax_codes(id), transaction_date date NOT NULL, direction text NOT NULL CHECK(direction IN ('INPUT','OUTPUT')), taxable_amount numeric(19,4) NOT NULL, tax_amount numeric(19,4) NOT NULL, source_type text NOT NULL, source_id uuid NOT NULL);
CREATE TABLE cash_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), account_id uuid NOT NULL REFERENCES accounts(id), name_ar text NOT NULL, account_kind text NOT NULL CHECK(account_kind IN ('CASH','BANK')), bank_name text, iban_last4 char(4), is_active boolean NOT NULL DEFAULT true, UNIQUE(company_id,account_id));
CREATE TABLE cash_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), cash_account_id uuid NOT NULL REFERENCES cash_accounts(id), transaction_no text NOT NULL, transaction_date date NOT NULL, direction text NOT NULL CHECK(direction IN ('RECEIPT','PAYMENT','TRANSFER')), amount numeric(19,4) NOT NULL CHECK(amount>0), counterparty_id uuid REFERENCES parties(id), journal_entry_id uuid REFERENCES journal_entries(id), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','POSTED','VOID')), UNIQUE(company_id,transaction_no));
CREATE TABLE bank_statement_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cash_account_id uuid NOT NULL REFERENCES cash_accounts(id), statement_date date NOT NULL, description text, amount numeric(19,4) NOT NULL, external_reference text, is_reconciled boolean NOT NULL DEFAULT false, UNIQUE(cash_account_id,external_reference));
CREATE TABLE bank_reconciliations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cash_account_id uuid NOT NULL REFERENCES cash_accounts(id), statement_ending_date date NOT NULL, statement_ending_balance numeric(19,4) NOT NULL, book_balance numeric(19,4) NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','COMPLETED')), completed_at timestamptz);
